values.flexJson:
={
  "type": "bubble",
  "header": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "🏛️ RefCare 轉介平台 (專案派案)",
        "color": "#ffe4e6",
        "size": "xs",
        "weight": "bold"
      },
      {
        "type": "text",
        "text": "{{ $('Webhook-困難派案').item.json.body.notify_type === 'update' ? '個案需求變更通知' : '社會局指派案' }}",
        "color": "#ffffff",
        "size": "xl",
        "weight": "bold",
        "margin": "xs"
      }
    ],
    "background": {
      "type": "linearGradient",
      "angle": "135deg",
      "startColor": "{{ $('Webhook-困難派案').item.json.body.notify_type === 'update' ? '#f59e0b' : '#881337' }}",
      "endColor": "{{ $('Webhook-困難派案').item.json.body.notify_type === 'update' ? '#d97706' : '#be123c' }}"
    },
    "paddingAll": "20px"
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "box",
        "layout": "horizontal",
        "contents": [
          {
            "type": "text",
            "text": "案件編號",
            "color": "#64748b",
            "size": "sm",
            "flex": 2
          },
          {
            "type": "text",
            "text": "{{ $('Webhook-困難派案').item.json.body.case_id }}",
            "color": "#9f1239",
            "size": "sm",
            "weight": "bold",
            "flex": 5
          }
        ]
      },
      {
        "type": "box",
        "layout": "horizontal",
        "contents": [
          {
            "type": "text",
            "text": "轉介醫院",
            "color": "#64748b",
            "size": "sm",
            "flex": 2
          },
          {
            "type": "text",
            "text": "{{ $('Webhook-困難派案').item.json.body.hospital }}",
            "color": "#1e293b",
            "size": "sm",
            "weight": "bold",
            "flex": 5
          }
        ],
        "margin": "md"
      },
      {
        "type": "separator",
        "margin": "lg",
        "color": "#f1f5f9"
      },
      {
        "type": "box",
        "layout": "vertical",
        "backgroundColor": "#fff1f2",
        "borderColor": "#f43f5e",
        "borderWidth": "normal",
        "cornerRadius": "md",
        "paddingAll": "md",
        "margin": "md",
        "contents": [
          {
            "type": "text",
            "text": "• 經衛生局及社會局評估，該案符合特殊情形個案之困難派案原則，依流程進行派案。",
            "color": "#be123c",
            "size": "xs",
            "wrap": true,
            "weight": "bold",
            "lineHeight": "1.5"
          },
          {
            "type": "text",
            "text": "📍 順序詢問：第 {{ ($('Webhook-困難派案').item.json.body.current_queue_index || 0) + 1 }} 家服務單位（請優先評估）",
            "color": "#9f1239",
            "size": "xs",
            "wrap": true,
            "weight": "bold",
            "margin": "xs",
            "lineHeight": "1.5"
          }
        ]
      },
      {
        "type": "box",
        "layout": "vertical",
        "contents": [
          {
            "type": "box",
            "layout": "horizontal",
            "contents": [
              {
                "type": "text",
                "text": "👤 案主背景",
                "color": "#475569",
                "size": "sm",
                "flex": 3
              },
              {
                "type": "text",
                "text": "{{ ($('Webhook-困難派案').item.json.body.patient_name || '無')[0] }}◯{{ $('Webhook-困難派案').item.json.body.gender === '男' ? '先生' : '女士' }} ({{ $('Webhook-困難派案').item.json.body.age }}歲)",
                "color": "#0f172a",
                "size": "sm",
                "weight": "bold",
                "flex": 4
              }
            ]
          },
          {
            "type": "box",
            "layout": "horizontal",
            "contents": [
              {
                "type": "text",
                "text": "♿ 失能等級",
                "color": "#475569",
                "size": "sm",
                "flex": 3
              },
              {
                "type": "text",
                "text": "{{ $('Webhook-困難派案').item.json.body.cms_level || '未評估' }}",
                "color": "#e11d48",
                "size": "sm",
                "weight": "bold",
                "flex": 4
              }
            ],
            "margin": "sm"
          },
          {
            "type": "box",
            "layout": "horizontal",
            "contents": [
              {
                "type": "text",
                "text": "💡 轉介項目",
                "color": "#475569",
                "size": "sm",
                "flex": 3
              },
              {
                "type": "text",
                "text": "{{ $('Webhook-困難派案').item.json.body.service_type }}",
                "color": "#0f172a",
                "size": "sm",
                "weight": "bold",
                "flex": 4
              }
            ],
            "margin": "sm"
          },
          {
            "type": "box",
            "layout": "horizontal",
            "contents": [
              {
                "type": "text",
                "text": "🛠️ 服務代碼",
                "color": "#475569",
                "size": "sm",
                "flex": 3
              },
              {
                "type": "text",
                "text": "{{ ($('Webhook-困難派案').item.json.body.service_codes || []).join(', ') || '無' }}",
                "color": "#0f172a",
                "size": "sm",
                "weight": "bold",
                "flex": 4
              }
            ],
            "margin": "sm"
          }
        ],
        "margin": "lg"
      }
    ],
    "paddingAll": "20px"
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "button",
        "action": {
          "type": "uri",
          "label": "⚡ 優先評估與回覆",
          "uri": "https://refcare.zeabur.app/facility.html?case_id={{ $('Webhook-困難派案').item.json.body.case_id }}"
        },
        "style": "primary",
        "color": "{{ $('Webhook-困難派案').item.json.body.notify_type === 'update' ? '#d97706' : '#be123c' }}",
        "height": "sm"
      }
    ],
    "paddingAll": "16px"
  }
}
